merge into T_CX_CLASS_SHIFT_FINISH_QTY a USING (
select #{ITEM.orderNo,jdbcType=VARCHAR} order_no, #{ITEM.scheduleDate,jdbcType=DATE} schedule_date, #{ITEM.cxMachineCode,jdbcType=VARCHAR} cx_machine_code, #{ITEM.sapCode,jdbcType=VARCHAR} sap_code, #{ITEM.embryoCode,jdbcType=VARCHAR} embryo_code, #{ITEM.sapClass1FinishQty,jdbcType=DECIMAL} sap_class1_finish_qty, #{ITEM.sapClass2FinishQty,jdbcType=DECIMAL} sap_class2_finish_qty, #{ITEM.sapClass3FinishQty,jdbcType=DECIMAL} sap_class3_finish_qty, #{ITEM.sapClass4FinishQty,jdbcType=DECIMAL} sap_class4_finish_qty, #{ITEM.sapClass5FinishQty,jdbcType=DECIMAL} sap_class5_finish_qty, #{ITEM.embryoCode,jdbcType=VARCHAR} production_stage, #{ITEM.class1FinishQty,jdbcType=DECIMAL} class1_finish_qty, #{ITEM.class2FinishQty,jdbcType=DECIMAL} class2_finish_qty, #{ITEM.class3FinishQty,jdbcType=DECIMAL} class3_finish_qty, #{ITEM.class4FinishQty,jdbcType=DECIMAL} class4_finish_qty, #{ITEM.class5FinishQty,jdbcType=DECIMAL} class5_finish_qty, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON (a.order_no = b.order_no and a.del_flag = '0') WHEN MATCHED THEN UPDATE SET a.sap_class1_finish_qty = b.sap_class1_finish_qty, a.sap_class2_finish_qty = b.sap_class2_finish_qty, a.sap_class3_finish_qty = b.sap_class3_finish_qty, a.sap_class4_finish_qty = b.sap_class4_finish_qty, a.sap_class5_finish_qty = b.sap_class5_finish_qty, a.class1_finish_qty= b.class1_finish_qty, a.class2_finish_qty= b.class2_finish_qty, a.class3_finish_qty= b.class3_finish_qty, a.class4_finish_qty= b.class4_finish_qty, a.class5_finish_qty= b.class5_finish_qty, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.order_no, a.schedule_date, a.cx_machine_code, a.sap_code , a.embryo_code , a.sap_class1_finish_qty , a.sap_class2_finish_qty , a.sap_class3_finish_qty , a.sap_class4_finish_qty , a.sap_class5_finish_qty , a.class1_finish_qty , a.class2_finish_qty , a.class3_finish_qty , a.class4_finish_qty , a.class5_finish_qty , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_CX_FINISH_QTY.NEXTVAL, b.order_no, b.schedule_date, b.cx_machine_code, b.sap_code, b.embryo_code, b.sap_class1_finish_qty, b.sap_class2_finish_qty, b.sap_class3_finish_qty, b.sap_class4_finish_qty, b.sap_class5_finish_qty, b.class1_finish_qty, b.class2_finish_qty, b.class3_finish_qty, b.class4_finish_qty, b.class5_finish_qty, b.create_by, sysdate, b.remark, '0' )

merge into T_CX_DAY_FINISH_QTY a USING (
select #{ITEM.finishDate,jdbcType=DATE} finish_date, #{ITEM.sapCode,jdbcType=VARCHAR} sap_code, #{ITEM.embryoCode,jdbcType=VARCHAR} embryo_code, #{ITEM.bomDataVersion,jdbcType=VARCHAR} BOM_DATA_VERSION, #{ITEM.dayFinishQty,jdbcType=DECIMAL} DAY_FINISH_QTY, #{ITEM.companyCode,jdbcType=VARCHAR} COMPANY_CODE, #{ITEM.factoryCode,jdbcType=VARCHAR} FACTORY_CODE, #{ITEM.dataVersion,jdbcType=VARCHAR} DATA_VERSION, #{ITEM.createDate,jdbcType=DATE} create_date, #{ITEM.updateDate,jdbcType=DATE} update_date, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.embryo_code = b.embryo_code and a.finish_date = b.finish_date and a.BOM_DATA_VERSION = b.BOM_DATA_VERSION and a.is_delete = '0' ) WHEN MATCHED THEN UPDATE SET a.DAY_FINISH_QTY = b.DAY_FINISH_QTY, a.update_date = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.finish_date, a.sap_code, a.embryo_code, a.BOM_DATA_VERSION , a.DAY_FINISH_QTY , a.COMPANY_CODE , a.FACTORY_CODE , a.DATA_VERSION , a.create_date , a.update_date , a.remark , a.is_delete ) values (SEQ_CX_FINISH_QTY.NEXTVAL, b.finish_date, b.sap_code, b.embryo_code, b.BOM_DATA_VERSION , b.DAY_FINISH_QTY , b.COMPANY_CODE , b.FACTORY_CODE , b.DATA_VERSION , b.create_date , b.update_date , b.remark, 0 )

